  public static List<List<Integer>> permute(int[] nums) {
      List<List<Integer>> result = new ArrayList<>();
      if (nums.length == 1) {
          result.add(Arrays.asList(nums));
          return result;
      }

      for (int i = 0; i < nums.length; i++) {
          int[] remainingNums = Arrays.copyOfRange(nums, 0, i)
                  .concat(Arrays.copyOfRange(nums, i + 1, nums.length));
          List<List<Integer>> subPermutations = permute(remainingNums);
          for (List<Integer> subPermutation : subPermutations) {
              subPermutation.add(0, nums[i]);
              result.add(subPermutation);
          }
      }
      return result;
  }
}
