public class LargestSubstringFinder {

    public int findLargestSubstring(List<String> strings) {
        if (strings == null || strings.isEmpty()) {
            throw new IllegalArgumentException("Input list of strings cannot be null or empty.");
        }

        Collections.sort(strings, Comparator.comparingInt(String::length));

        int largestSubstring = 0;
        for (int i = 0; i < strings.size(); i++) {
            for (int j = i + 1; j < strings.size(); j++) {
                if (Arrays.stream(strings.get(i).split(strings.get(j))).anyMatch(s -> s.length() > largestSubstring)) {
                    largestSubstring = Math.max(strings.get(i).length(), strings.get(j).length());
                }
            }
        }

        return largestSubstring;
    }
