public int findLargestSubstring(List<String> strings) {
    int maxLen = 0;
    for (String s : strings) {
        if (s.length() > maxLen) {
            maxLen = s.length();
        }
    }

    for (int i = 0; i < maxLen; i++) {
        String substr = strings.get(0).substring(i);
        for (String s : strings) {
            if (s.contains(substr) || s.contains(substr.reverse())) {
                return i + 1;
            }
        }
    }

    return 0;
}
