    for (int i = 1; i <= N; i++) {
        // Check if the number of regions has been recorded
        if (results.contains(i)) {
            // If yes, set the maximum number of regions to the current value
            maxRegions = i;
        } else {
            // If no, record the current number of regions and set the maximum
            results.add(i);
            maxRegions = i;
        }
    }

    return maxRegions;
}
