public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Initialize a bool array to keep track of visited nodes
    boolean[] visited = new boolean[n];

    // Use a queue to keep track of nodes to visit
    Queue<int[]> queue = new LinkedList<>();
    queue.offer(start);

    // Visit the starting node and mark it as visited
    visited[start[0] * n + start[1]] = true;

    // Loop until the queue is empty
    while (!queue.isEmpty()) {
        // Get the current node
        int[] current = queue.poll();

        // If the current node is the ending node, return "can be travelled"
        if (current[0] == end[0] && current[1] == end[1]) {
            return "can be travelled";
        }

        // Loop through all adjacent nodes
        for (int[] path : paths) {
            // If the current node matches the adjacent node and the adjacent node has not been visited,
            // mark it as visited and enqueue it for visiting
            if (current[0] == path[0] && current[1] == path[1] && !visited[path[2] * n + path[3]]) {
                visited[path[2] * n + path[3]] = true;
                queue.offer(path);
            }
        }
    }

    // If all nodes have been visited and the ending node is not reached, return "cannot be travelled"
    return "cannot be travelled";
}
