public int search(int[] nums, int target) {
    // Base case: if the array has only one element, return -1 if the target is not equal to the element
    if (nums.length == 1) {
        return nums[0] == target ? 0 : -1;
    }

    // Find the pivot index
    int pivotIndex = findPivotIndex(nums);

    // If the pivot index is 0, the array is sorted and the target value is not in the array, return -1
    if (pivotIndex == 0 && nums[0] > target) {
        return -1;
    }

    // If the pivot index is not 0 and the target value is not in the array, return -1
    if (pivotIndex != 0 && !inArray(nums, target, pivotIndex)) {
        return -1;
    }

    // If the target value is in the array, return its index
    return binarySearch(nums, target);
}

private int findPivotIndex(int[] nums) {
    // If the array has only one element, return 0
    if (nums.length == 1) {
        return 0;
    }

    // If the array has more than one element, find the pivot index
    for (int i = 1; i < nums.length; i++) {
        if (nums[i] < nums[i - 1]) {
            return i;
        }
    }

    // If the array has no rotations, return 0
    return 0;
}

private boolean inArray(int[] nums, int target, int pivotIndex) {
    // If the target value is less than the pivot element, it is in the left sub-array
    if (target < nums[pivotIndex]) {
        return binarySearch(nums, 0, pivotIndex - 1, target) != -1;
    }

    // If the target value is greater than the pivot element, it is in the right sub-array
    return binarySearch(nums, pivotIndex + 1, nums.length - 1, target) != -1;
}

private int binarySearch(int[] nums, int target) {
    return binarySearch(nums, 0, nums.length - 1, target);
}

private int binarySearch(int[] nums, int low, int high, int target) {
    // If the high index is less than or equal to the low index, return -1
    if (high < low) {
        return -1;
    }

    // Find the middle index
    int mid = (low + high) / 2;

    // If the target value is less than the middle element, search the left sub-array
    if (nums[mid] > target) {
        return binarySearch(nums, low, mid - 1, target);
    }

    // If the target value is greater than the middle element, search the right sub-array
    if (nums[mid] < target) {
        return binarySearch(nums, mid + 1, high, target);
    }

    // If the target value is equal to the middle element, return its index
    return mid;
}

