    // handle edge case of a single-element array
    if (nums.length == 1) {
        if (nums[0] == target) {
            return 0;
        } else {
            return -1;
        }
    }

    // find the pivot index
    int pivotIndex = findPivotIndex(nums);

    // handle the case where the target is in the left subarray
    if (nums[pivotIndex] == target) {
        return pivotIndex;
    }
    if (nums[0] <= target && target < nums[pivotIndex]) {
        return binarySearch(nums, 0, pivotIndex, target);
