    // handle the case where the target is in the right subarray
    if (nums[pivotIndex] < target && target <= nums[nums.length - 1]) {
        return binarySearch(nums, pivotIndex + 1, nums.length - 1, target);
    }

    // target is not found
    return -1;
}

