public double trimMean(int[] arr) {
    // Find the smallest 5% of the elements
    int minIndex = 0;
    int min = arr[0];
    for (int i = 0; i < arr.length; i++) {
        if (arr[i] < min) {
            minIndex = i;
            min = arr[i];
        }
    }
    int startIndex = minIndex - (int) (arr.length * 0.05);
    if (startIndex < 0) startIndex = 0;
    // Find the largest 5% of the elements
    int maxIndex = arr.length - 1;
    int max = arr[maxIndex];
    for (int i = arr.length - 1; i >= 0; i--) {
        if (arr[i] > max) {
            maxIndex = i;
            max = arr[i];
        }
    }
    int endIndex = maxIndex + (int) (arr.length * 0.05);
    if (endIndex > arr.length - 1) endIndex = arr.length - 1;
    // Calculate the sum of the elements in the remaining range
    int sum = 0;
    for (int i = startIndex; i <= endIndex; i++) {
        sum += arr[i];
    }
    // Calculate the mean
    return (double) sum / (endIndex - startIndex + 1);
