/**
 * Given a binary string s and an integer k,
 * return true if every binary string of length k is a substring of s,
 * or false otherwise.
 */
public boolean hasAllCodes(String s, int k) {
    // Check if the input string is null or empty
    if (s == null || s.length() == 0) return false;

    // Check if the length of the input string is not a multiple of k
    if (s.length() % k != 0) return false;

    // Create a hash table to keep track of the substrings
    Map<String, Integer> substrings = new HashMap<>();

    // Iterate over the input string in chunks of length k
    for (int i = 0; i < s.length(); i += k) {
        // Extract the current substring
        String current = s.substring(i, i + k);

        // Check if the substring is already present in the hash table
        if (substrings.containsKey(current)) {
            // If the substring is already present, increment its count
            substrings.put(current, substrings.get(current) + 1);
        } else {
            // If the substring is not present, add it to the hash table
            substrings.put(current, 1);
        }
    }

    // Check if the hash table contains every possible substring
    for (int i = 0; i < (1 << k); i++) {
        // Extract the bit string for the current substring
        String bitString = String.format("%" + k + "s", Integer.toBinaryString(i)).replace(' ', '0');

        // Check if the substring is present in the hash table
        if (!substrings.containsKey(bitString)) {
            // If the substring is not present, return false
            return false;
        }
    }

    // If we reach this point, all substrings are present, so return true
    return true;
}

