public static int findMinFibonacciNumbers(int k) {
    if (k <= 1) return 0;

    int[] fibonacci = new int[k + 1];
    fibonacci[1] = 1;
    for (int i = 2; i <= k; i++) {
        fibonacci[i] = fibonacci[i - 1] + fibonacci[i - 2];
    }

    int j = k;
    int count = 0;
    while (j > 0) {
        if (fibonacci[j] == j) {
            j = 0;
        } else {
            j -= fibonacci[j];
            count++;
        }
    }

    return count;
}
