        fib[i] = fib[i - 1] + fib[i - 2];
    }

    int min = Integer.MAX_VALUE;
    for (int i = k; i >= 0; i--) {
        if (fib[i] >= k) {
            min = Math.min(min, i);
            break;
        }
    }

    return min + 1;
}

