public String makeGood(String s) {
    StringBuilder result = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char currentChar = s.charAt(i);

        // If the current character is not in uppercase or next character is not in lowercase,
        // add the current character to the result string and continue.
        if (!Character.isUpperCase(currentChar) || i == s.length() - 1 || !Character.isLowerCase(s.charAt(i + 1))) {
            result.append(currentChar);
            continue;
        }

        // If the current character is in uppercase and next character is in lowercase,
        // add the next character to the result string, since it will become uppercase in the next iteration.
        result.append(s.charAt(i + 1));
    }

    return result.toString().toLowerCase();
}
