public static List<Integer> findSteppingNumbers(int low, int high) {
    int size = high - low + 1;
    List<Integer> result = new ArrayList<>(size);

    // Initialize the queue with the first digit
    Queue<String> que = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        que.offer(String.valueOf(i));
    }

    int count = 0;

    // Iterate over the queue and add the next digit
    // until the upper bound is reached
    while (!que.isEmpty() && count <= high) {
        String num = que.poll();
        if (count++ == low) {
            result.add(Integer.parseInt(num));
        }
        int lastDigit = num.charAt(num.length() - 1) - '0';
        if (lastDigit > 0) {
            que.offer(num + (lastDigit - 1));
        }
        if (lastDigit < 9) {
            que.offer(num + (lastDigit + 1));
        }
    }
    return result;
}
```
