private static int dfs(int[][] mat, int i, int j, boolean[][] visited) {
    if (i < 0 || j < 0 || i >= mat.length || j >= mat[0].length || mat[i][j] == 0 || visited[i][j]) {
        return 0;
    }

    visited[i][j] = true;
    int length = 1 + dfs(mat, i + 1, j, visited) + dfs(mat, i, j + 1, visited);

    return length;
}
