public static int squarePermutations(int[] A) {
    // Edge case: If the input array is empty, there is only one permutation
    if (A.length == 0) {
        return 1;
    }

    // Count the number of permutations that have a sum of adjacent elements as a perfect square
    int count = 0;
    for (int i = 0; i < A.length - 1; i++) {
        int sum = A[i] + A[i + 1];
        if (sum % 2 == 0 && Math.sqrt(sum) == Math.floor(Math.sqrt(sum))) {
            count++;
        }
    }

    // Count the number of permutations that have a sum of the last element with an element in the first position as a perfect square
    int lastElement = A[A.length - 1];
    int firstElement = A[0];
    int sum = lastElement + firstElement;
    if (sum % 2 == 0 && Math.sqrt(sum) == Math.floor(Math.sqrt(sum))) {
        count++;
    }

    // Calculate the number of permutations based on the count of square sums
    int numPermutations = Math.pow(2, A.length - 1);
    int[][] permutations = new int[numPermutations][A.length];

    // Initialize the permutations array with all possible permutations of the input array
    int index = 0;
    for (int i = 0; i < A.length; i++) {
        permutations[index][i] = A[i];
        index++;
    }
    for (int i = A.length - 1; i >= 1; i--) {
        for (int j = 0; j < i; j++) {
            permutations[index][j] = A[j];
            permutations[index][i] = A[i];
            index++;
        }
    }

    // Count the number of permutations that have a sum of adjacent elements as a perfect square
    int squarePermutations = 0;
    for (int[] permutation : permutations) {
        int sum = 0;
        for (int i = 0; i < permutation.length - 1; i++) {
            sum += permutation[i] + permutation[i + 1];
        }
        if (sum % 2 == 0 && Math.sqrt(sum) == Math.floor(Math.sqrt(sum))) {
            squarePermutations++;
        }
    }

    // Return the number of square permutations of A
    return squarePermutations;
}

