    for (int i = 0; i < A.length; i++) {
        // Find the sum of the adjacent elements
        int sum = 0;
        for (int j = i - 1; j < i + 2; j++) {
            if (j >= 0 && j < A.length) {
                sum += A[j];
            }
        }

        // If the sum is a perfect square, add it to the set of permutations
        if (sum % Math.sqrt(sum) == 0) {
            permutations.add(sum);
        }
    }

    // Return the number of unique permutations
    return permutations.size();
