        Arrays.sort(copy);
        int result = 0;

        for (int i = 0; i < A.length; i++) {
            if (copy[i] == 0) {
                continue;
            }

            if (isSquare(copy[i])) {
                for (int j = i + 1; j < A.length; j++) {
                    if (copy[j] == 0) {
                        continue;
                    }

                    if (isSquare(copy[j])) {
                        result++;
                    }
                }
            }
        }

        return result;
    }

    private static boolean isSquare(int n) {
        int squareRoot = (int) Math.floor(Math.sqrt(n));
        return squareRoot * squareRoot == n;
    }
