public static int squarePermutations(int[] A) {
    // Calculate the sum of each pair of adjacent elements in A
    int[] sums = new int[A.length - 1];
    for (int i = 1; i < A.length; i++) {
        sums[i - 1] = A[i] + A[i - 1];
    }

    // Count the number of perfect squares in sums
    int count = 0;
    for (int sum : sums) {
        int root = (int) Math.sqrt(sum);
        if (root * root == sum) {
            count++;
        }
    }

    // Calculate the total number of permutations of A
    int total = 1;
    for (int i = 0; i < A.length; i++) {
        total *= A.length - i;
    }

    // Return the number of square permutations of A
    return count * total;
}
