public static int largestRectangleArea(int[] heights) {
    int n = heights.length;
    int[] left = new int[n];
    int[] right = new int[n];

    left[0] = 0;
    for (int i = 1; i < n; i++) {
        int j = i - 1;
        while (j >= 0 && heights[i] > heights[j]) {
            j = left[j];
        }
        left[i] = j;
    }

    right[n - 1] = n;
    for (int i = n - 2; i >= 0; i--) {
        int j = i + 1;
        while (j < n && heights[i] > heights[j]) {
            j = right[j];
        }
        right[i] = j;
    }

    int maxArea = 0;
    for (int i = 0; i < n; i++) {
        maxArea = Math.max(maxArea, heights[i] * (right[i] - left[i] - 1));
    }

    return maxArea;
}
